        var claims = List.of(
                new ClaimPicker.Claim("C1", LocalDate.of(2026, 1, 10)),
                new ClaimPicker.Claim("C2", LocalDate.of(2026, 3, 2)),
                new ClaimPicker.Claim("C3", LocalDate.of(2026, 2, 14)));
