import java.time.LocalDate;
import java.util.List;

public final class ClaimPicker {

    public record Claim(String id, LocalDate incidentDate) {
    }

    public Claim latest(List<Claim> claims) {
        if (claims == null || claims.isEmpty()) {
            return null;
        }
        Claim best = claims.get(0);
        for (int index = 1; index < claims.size(); index += 1) {
            Claim candidate = claims.get(index);
            int byDate = candidate.incidentDate().compareTo(best.incidentDate());
            if (byDate > 0 || (byDate == 0 && candidate.id().compareTo(best.id()) > 0)) {
                best = candidate;
            }
        }
        return best;
    }
}

